-- ---------------------------------------------------------------------------
-- 1. Shows — dates relative to today in America/New_York
-- ---------------------------------------------------------------------------
create temp table _cal_today on commit drop as
select (now() at time zone 'America/New_York')::date as d0;

create temp table _cal_shows on commit drop as
select v.id::uuid as id, v.key, v.name, v.slug, v.venue_id::uuid as venue_id, v.days,
       t.d0 + v.start_off as start_d,
       t.d0 + v.start_off + v.days - 1 as end_d,
       t.d0 + v.open_off as open_d,
       t.d0 + v.close_off as close_d,
       v.close_time,
       ((t.d0 + v.published_off)::timestamp + time '09:30') at time zone 'America/New_York' as published_at,
       v.runner_state, v.show_type, v.governing_bodies, v.locations, v.starting_rider_number,
       v.document_requirements, v.expenses
from (values
  ('f38106d9-dc18-4195-a57b-efebea1edf99', 'live', 'Wills Park Dressage Classic', 'wills-park-dressage-classic', 'b0000000-0000-4000-8000-000000000007', 2, 0, -42, -3, null, -45, '{"ticketClosed":true,"approved":true}'::jsonb, 'rated', '["USEF","USDF"]'::jsonb, '[{"name":"Main Arena","size":"standard"},{"name":"Covered Arena","size":"standard"},{"name":"Warm-up Ring","size":"small"}]'::jsonb, 201, '[{"id":"dr-live-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true},{"id":"dr-live-health","label":"Health Certificate","requiresExpiration":true,"requiresApproval":false}]'::jsonb, '[{"id":"e1","label":"Judge fees","amount":3600},{"id":"e2","label":"Facility rental","amount":5200},{"id":"e3","label":"Ribbons and awards","amount":980},{"id":"e4","label":"Shavings","amount":1400},{"id":"e5","label":"EMT and farrier on call","amount":900}]'::jsonb),
  ('d21b06c6-1315-44af-968f-c2c98b4d2ca3', 'last-chance', 'Chattahoochee River Dressage Days', 'chattahoochee-river-dressage-days', 'b0000000-0000-4000-8000-000000000009', 2, 2, -35, 1, '20:00', -38, '{}'::jsonb, 'rated', '["USEF","USDF"]'::jsonb, '[{"name":"Indoor Arena","size":"standard"},{"name":"Outdoor Arena","size":"standard"},{"name":"Schooling Ring","size":"small"}]'::jsonb, 301, '[{"id":"dr-last-chance-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true},{"id":"dr-last-chance-health","label":"Health Certificate","requiresExpiration":true,"requiresApproval":false}]'::jsonb, '[{"id":"e1","label":"Judge fees","amount":3400},{"id":"e2","label":"Facility rental","amount":4800},{"id":"e3","label":"Ribbons and awards","amount":900}]'::jsonb),
  ('2cb46297-13a1-48d2-ad88-7dfa32ba0cce', 'two-weeks', 'Lowcountry Dressage Festival', 'lowcountry-dressage-festival', 'b0000000-0000-4000-8000-00000000000a', 2, 14, -7, 10, '23:59', -9, '{}'::jsonb, 'rated', '["USEF","USDF"]'::jsonb, '[{"name":"Oak Arena","size":"standard"},{"name":"Marsh Arena","size":"standard"}]'::jsonb, 401, '[{"id":"dr-two-weeks-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true},{"id":"dr-two-weeks-health","label":"Health Certificate","requiresExpiration":true,"requiresApproval":false}]'::jsonb, '[]'::jsonb),
  ('9ae451a8-67e0-4460-ba72-34b7177c2815', 'four-weeks', 'Peachtree Park Schooling Show', 'peachtree-park-schooling-show', 'b0000000-0000-4000-8000-000000000008', 1, 28, -3, 24, null, -5, '{}'::jsonb, 'schooling', '[]'::jsonb, '[{"name":"Ring 1","size":"standard"},{"name":"Ring 2","size":"standard"}]'::jsonb, 501, '[{"id":"dr-four-weeks-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true}]'::jsonb, '[]'::jsonb),
  ('aaa77721-4b0b-4147-85b5-ce6bfb0c917d', 'seven-weeks', 'North Georgia Dressage Invitational', 'north-georgia-dressage-invitational', 'b0000000-0000-4000-8000-000000000007', 2, 49, 14, 45, null, -2, '{}'::jsonb, 'rated', '["USEF","USDF"]'::jsonb, '[{"name":"Main Arena","size":"standard"},{"name":"Covered Arena","size":"standard"},{"name":"Warm-up Ring","size":"small"}]'::jsonb, 601, '[{"id":"dr-seven-weeks-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true},{"id":"dr-seven-weeks-health","label":"Health Certificate","requiresExpiration":true,"requiresApproval":false}]'::jsonb, '[]'::jsonb),
  ('8fd739a4-a494-46c9-b153-035a211b9221', 'ten-weeks', 'Southeast Regional Dressage Championships', 'southeast-regional-dressage-championships', 'b0000000-0000-4000-8000-000000000009', 3, 70, 30, 66, null, -1, '{}'::jsonb, 'rated', '["USEF","USDF"]'::jsonb, '[{"name":"Indoor Arena","size":"standard"},{"name":"Outdoor Arena","size":"standard"},{"name":"Schooling Ring","size":"small"}]'::jsonb, 701, '[{"id":"dr-ten-weeks-coggins","label":"Coggins","requiresExpiration":true,"requiresApproval":true},{"id":"dr-ten-weeks-health","label":"Health Certificate","requiresExpiration":true,"requiresApproval":false}]'::jsonb, '[]'::jsonb)
) as v(id, key, name, slug, venue_id, days, start_off, open_off, close_off, close_time, published_off,
       runner_state, show_type, governing_bodies, locations, starting_rider_number, document_requirements, expenses)
cross join _cal_today t;

insert into public.shows (
  id, org_id, venue_id, venue_name, name, slug, date_label, start_date, end_date, status, disciplines, governing_bodies,
  show_type, published, published_at, timezone, ticket_open, ticket_close, locations, day_start_times, day_end_times,
  runner_state, show_details, starting_rider_number, document_requirements, waiver_text, waiver_approved_at,
  waiver_approved_text, expenses, created_at
)
select s.id, 'a0000000-0000-4000-8000-000000000004', s.venue_id, v.name, s.name, s.slug,
       case when s.start_d = s.end_d then to_char(s.start_d, 'Mon FMDD, YYYY')
            else to_char(s.start_d, 'Mon FMDD') || ' – ' || to_char(s.end_d, 'Mon FMDD, YYYY') end,
       to_char(s.start_d, 'YYYY-MM-DD'), to_char(s.end_d, 'YYYY-MM-DD'),
       'green', '["Dressage"]'::jsonb, s.governing_bodies, s.show_type, true, s.published_at, 'America/New_York',
       to_char(s.open_d, 'YYYY-MM-DD'),
       to_char(s.close_d, 'YYYY-MM-DD') || coalesce(' ' || s.close_time, ''),
       s.locations,
       (select jsonb_agg('08:00'::text) from generate_series(1, s.days)),
       (select jsonb_agg('17:00'::text) from generate_series(1, s.days)),
       s.runner_state,
       jsonb_build_object('org', 'Peachtree Dressage Association', 'phone', '770-555-0142',
                          'website', 'https://www.peachtreedressage.example',
                          'contactEmail', 'secretary@fieldarena-demo.test',
                          'prizeListUrl', 'https://www.peachtreedressage.example/prize-lists/' || s.slug),
       s.starting_rider_number, s.document_requirements,
       w.waiver_text, case when w.waiver_text is not null then s.published_at - interval '15 minutes' end, w.waiver_text,
       s.expenses, s.published_at - interval '6 days'
from _cal_shows s
join public.venues v on v.id = s.venue_id
cross join (select coalesce((select waiver_text from public.shows where id = 'c0000000-0000-4000-8000-000000000001'),
                            (select waiver_text from public.shows where org_id = 'a0000000-0000-4000-8000-000000000004' and waiver_text is not null
                              order by created_at limit 1)) as waiver_text) w
on conflict (id) do update set
  date_label   = excluded.date_label,
  start_date   = excluded.start_date,
  end_date     = excluded.end_date,
  ticket_open  = excluded.ticket_open,
  ticket_close = excluded.ticket_close,
  published    = true,
  published_at = excluded.published_at,
  runner_state = excluded.runner_state,
  waiver_approved_at = case when shows.waiver_approved_text is not null then excluded.waiver_approved_at end
where shows.start_date is distinct from excluded.start_date
   or shows.ticket_open is distinct from excluded.ticket_open
   or shows.ticket_close is distinct from excluded.ticket_close
   or shows.published is distinct from true
   or shows.runner_state is distinct from excluded.runner_state;

